-- INDINEXT 13-week starter quiz bank. General sales/service process; edit questions from Super Admin.
-- Additive constraints: one attempt per agent/week and no duplicate question text within a week.
CREATE UNIQUE INDEX IF NOT EXISTS ux_quiz_attempts_agent_week ON quiz_attempts(agent_id, week_number);
CREATE UNIQUE INDEX IF NOT EXISTS ux_quiz_question_week_text ON quiz_questions(week_number, question);
INSERT OR IGNORE INTO quiz_questions(week_number,question,options_json,correct_index,explanation,is_active,created_at,updated_at) VALUES(1,'What is the best way to begin a customer call?','["Start pitching immediately","Greet the customer, introduce yourself and confirm it is a convenient time","Ask for payment details"]',1,'A polite introduction and permission set a professional tone.',1,'2026-11-05T13:30:00.000Z','2026-11-05T13:30:00.000Z');
INSERT OR IGNORE INTO quiz_questions(week_number,question,options_json,correct_index,explanation,is_active,created_at,updated_at) VALUES(1,'If a customer is speaking, what should an agent do?','["Interrupt to save time","Listen fully and clarify when needed","Assume the requirement"]',1,'Active listening reduces misunderstandings.',1,'2026-11-05T13:30:00.000Z','2026-11-05T13:30:00.000Z');
INSERT OR IGNORE INTO quiz_questions(week_number,question,options_json,correct_index,explanation,is_active,created_at,updated_at) VALUES(1,'If you do not know an answer, what is the best response?','["Guess confidently","Ignore the question","Be honest and confirm the correct information before responding"]',2,'Never invent product or policy information.',1,'2026-11-05T13:30:00.000Z','2026-11-05T13:30:00.000Z');
INSERT OR IGNORE INTO quiz_questions(week_number,question,options_json,correct_index,explanation,is_active,created_at,updated_at) VALUES(2,'Which detail helps establish a customer''s buying timeline?','["Preferred installation or decision date","Favourite colour only","Agent''s shift timing"]',0,'Timeline helps prioritize and plan follow-up.',1,'2026-11-05T13:30:00.000Z','2026-11-05T13:30:00.000Z');
INSERT OR IGNORE INTO quiz_questions(week_number,question,options_json,correct_index,explanation,is_active,created_at,updated_at) VALUES(2,'Why should an agent ask about the customer''s budget range?','["To pressure the customer","To recommend suitable options within expectations","To end the call quickly"]',1,'Budget context helps make relevant recommendations.',1,'2026-11-05T13:30:00.000Z','2026-11-05T13:30:00.000Z');
INSERT OR IGNORE INTO quiz_questions(week_number,question,options_json,correct_index,explanation,is_active,created_at,updated_at) VALUES(2,'A lead is qualified when the agent has understood:','["Only the customer''s first name","Need, contact details and a realistic next step","Only the call duration"]',1,'Qualification is based on useful customer context and a next action.',1,'2026-11-05T13:30:00.000Z','2026-11-05T13:30:00.000Z');
INSERT OR IGNORE INTO quiz_questions(week_number,question,options_json,correct_index,explanation,is_active,created_at,updated_at) VALUES(3,'What is a useful discovery question?','["What are you looking to improve or install?","Can you pay today?","Why are you calling?"]',0,'Open questions uncover the actual requirement.',1,'2026-11-05T13:30:00.000Z','2026-11-05T13:30:00.000Z');
INSERT OR IGNORE INTO quiz_questions(week_number,question,options_json,correct_index,explanation,is_active,created_at,updated_at) VALUES(3,'After hearing the requirement, an agent should:','["Repeat the key points to confirm understanding","Immediately end the call","Change the customer''s requirement"]',0,'A short recap confirms that both sides understood the need.',1,'2026-11-05T13:30:00.000Z','2026-11-05T13:30:00.000Z');
INSERT OR IGNORE INTO quiz_questions(week_number,question,options_json,correct_index,explanation,is_active,created_at,updated_at) VALUES(3,'If a customer has multiple requirements, the agent should:','["Record each requirement clearly","Remember only the first item","Ask the customer to call again"]',0,'Complete notes help prevent missed requirements.',1,'2026-11-05T13:30:00.000Z','2026-11-05T13:30:00.000Z');
INSERT OR IGNORE INTO quiz_questions(week_number,question,options_json,correct_index,explanation,is_active,created_at,updated_at) VALUES(4,'When a customer asks about windows, doors or mesh, the agent should first:','["Understand the intended use and preference","Promise the lowest price","Assume the dimensions"]',0,'Use case and preferences guide the next discussion.',1,'2026-11-05T13:30:00.000Z','2026-11-05T13:30:00.000Z');
INSERT OR IGNORE INTO quiz_questions(week_number,question,options_json,correct_index,explanation,is_active,created_at,updated_at) VALUES(4,'If asked for a technical specification you cannot verify, you should:','["Make up a specification","Confirm with the technical team or approved product information","Avoid recording the question"]',1,'Only verified specifications should be shared.',1,'2026-11-05T13:30:00.000Z','2026-11-05T13:30:00.000Z');
INSERT OR IGNORE INTO quiz_questions(week_number,question,options_json,correct_index,explanation,is_active,created_at,updated_at) VALUES(4,'What should be captured for a product enquiry?','["Product category, quantity or areas, preferences and open questions","Only the customer''s city","Only the agent''s opinion"]',0,'A clear requirement summary supports accurate quotation.',1,'2026-11-05T13:30:00.000Z','2026-11-05T13:30:00.000Z');
INSERT OR IGNORE INTO quiz_questions(week_number,question,options_json,correct_index,explanation,is_active,created_at,updated_at) VALUES(5,'Before confirming a site visit, an agent should:','["Confirm address, contact person and suitable time","Assume the address from caller ID","Book without asking"]',0,'A confirmed location and time avoid missed visits.',1,'2026-11-05T13:30:00.000Z','2026-11-05T13:30:00.000Z');
INSERT OR IGNORE INTO quiz_questions(week_number,question,options_json,correct_index,explanation,is_active,created_at,updated_at) VALUES(5,'Who should confirm technical measurements?','["A qualified/assigned measurement person following the process","Any person guessing from a photo","The customer without guidance"]',0,'Measurements must follow the organization''s approved process.',1,'2026-11-05T13:30:00.000Z','2026-11-05T13:30:00.000Z');
INSERT OR IGNORE INTO quiz_questions(week_number,question,options_json,correct_index,explanation,is_active,created_at,updated_at) VALUES(5,'If a site visit must be rescheduled, the agent should:','["Notify the customer promptly and agree a new time","Say nothing","Mark it completed"]',0,'Prompt updates maintain trust and accurate records.',1,'2026-11-05T13:30:00.000Z','2026-11-05T13:30:00.000Z');
INSERT OR IGNORE INTO quiz_questions(week_number,question,options_json,correct_index,explanation,is_active,created_at,updated_at) VALUES(6,'When explaining a quotation, the agent should:','["Explain included items, assumptions and any exclusions","Hide charges until later","Promise unapproved discounts"]',0,'Transparent explanations reduce disputes.',1,'2026-11-05T13:30:00.000Z','2026-11-05T13:30:00.000Z');
INSERT OR IGNORE INTO quiz_questions(week_number,question,options_json,correct_index,explanation,is_active,created_at,updated_at) VALUES(6,'If a customer asks for a discount beyond your authority, you should:','["Approve it anyway","Escalate or confirm with the authorized person","Ignore the request"]',1,'Pricing exceptions require proper approval.',1,'2026-11-05T13:30:00.000Z','2026-11-05T13:30:00.000Z');
INSERT OR IGNORE INTO quiz_questions(week_number,question,options_json,correct_index,explanation,is_active,created_at,updated_at) VALUES(6,'A quotation should be based on:','["Verified requirements and approved pricing","A guess to win the lead","Another customer''s quotation"]',0,'Accurate inputs support a reliable quotation.',1,'2026-11-05T13:30:00.000Z','2026-11-05T13:30:00.000Z');
INSERT OR IGNORE INTO quiz_questions(week_number,question,options_json,correct_index,explanation,is_active,created_at,updated_at) VALUES(7,'What is the best follow-up practice?','["Agree on a suitable time and record the next action","Call repeatedly without checking","Wait indefinitely"]',0,'Agreed follow-ups are respectful and actionable.',1,'2026-11-05T13:30:00.000Z','2026-11-05T13:30:00.000Z');
INSERT OR IGNORE INTO quiz_questions(week_number,question,options_json,correct_index,explanation,is_active,created_at,updated_at) VALUES(7,'A customer does not answer a callback. The agent should:','["Follow the approved retry process and log the attempt","Mark the lead won","Share the number publicly"]',0,'Consistent retry rules and notes preserve lead history.',1,'2026-11-05T13:30:00.000Z','2026-11-05T13:30:00.000Z');
INSERT OR IGNORE INTO quiz_questions(week_number,question,options_json,correct_index,explanation,is_active,created_at,updated_at) VALUES(7,'A useful CRM follow-up note includes:','["Date, customer response and next action","Only ''called''","Personal opinions"]',0,'Specific notes make the next interaction useful.',1,'2026-11-05T13:30:00.000Z','2026-11-05T13:30:00.000Z');
INSERT OR IGNORE INTO quiz_questions(week_number,question,options_json,correct_index,explanation,is_active,created_at,updated_at) VALUES(8,'When a customer says the price is high, the agent should first:','["Acknowledge the concern and understand what they are comparing","Argue with the customer","End the call"]',0,'Empathy and clarification reveal the real concern.',1,'2026-11-05T13:30:00.000Z','2026-11-05T13:30:00.000Z');
INSERT OR IGNORE INTO quiz_questions(week_number,question,options_json,correct_index,explanation,is_active,created_at,updated_at) VALUES(8,'If a customer says they need time to decide, the agent should:','["Respect the decision and agree on a follow-up if welcome","Pressure them to decide immediately","Close the lead as won"]',0,'Respectful follow-up keeps communication open.',1,'2026-11-05T13:30:00.000Z','2026-11-05T13:30:00.000Z');
INSERT OR IGNORE INTO quiz_questions(week_number,question,options_json,correct_index,explanation,is_active,created_at,updated_at) VALUES(8,'A good response to a complaint is to:','["Listen, acknowledge, record facts and route it appropriately","Blame another team","Make promises you cannot keep"]',0,'A clear process is better than unsupported promises.',1,'2026-11-05T13:30:00.000Z','2026-11-05T13:30:00.000Z');
INSERT OR IGNORE INTO quiz_questions(week_number,question,options_json,correct_index,explanation,is_active,created_at,updated_at) VALUES(9,'Why should employee and customer details be entered accurately?','["To keep records searchable and prevent wrong follow-ups","To make forms longer","It is not important"]',0,'Accurate records support reliable reporting and service.',1,'2026-11-05T13:30:00.000Z','2026-11-05T13:30:00.000Z');
INSERT OR IGNORE INTO quiz_questions(week_number,question,options_json,correct_index,explanation,is_active,created_at,updated_at) VALUES(9,'Before creating a new customer record, check for:','["An existing matching record to avoid duplicates","The weather","Another agent''s password"]',0,'Duplicate checks protect record quality.',1,'2026-11-05T13:30:00.000Z','2026-11-05T13:30:00.000Z');
INSERT OR IGNORE INTO quiz_questions(week_number,question,options_json,correct_index,explanation,is_active,created_at,updated_at) VALUES(9,'Which status should be selected in the CRM?','["The actual current stage supported by the latest interaction","The most positive status","A random status"]',0,'Statuses should reflect verified progress.',1,'2026-11-05T13:30:00.000Z','2026-11-05T13:30:00.000Z');
INSERT OR IGNORE INTO quiz_questions(week_number,question,options_json,correct_index,explanation,is_active,created_at,updated_at) VALUES(10,'A confirmed customer handover should include:','["Customer requirement, agreed scope, contact details and pending actions","Only the customer name","An unverified completion date"]',0,'A complete handover reduces gaps between teams.',1,'2026-11-05T13:30:00.000Z','2026-11-05T13:30:00.000Z');
INSERT OR IGNORE INTO quiz_questions(week_number,question,options_json,correct_index,explanation,is_active,created_at,updated_at) VALUES(10,'If an installation schedule changes, the customer should be:','["Updated through the approved communication process","Left to discover it later","Given an unconfirmed date"]',0,'Timely updates help customers plan.',1,'2026-11-05T13:30:00.000Z','2026-11-05T13:30:00.000Z');
INSERT OR IGNORE INTO quiz_questions(week_number,question,options_json,correct_index,explanation,is_active,created_at,updated_at) VALUES(10,'After a service issue is reported, the agent should:','["Record the issue and route it to the responsible team","Ignore the issue","Promise an immediate fix without checking"]',0,'Accurate routing ensures the issue reaches the right team.',1,'2026-11-05T13:30:00.000Z','2026-11-05T13:30:00.000Z');
INSERT OR IGNORE INTO quiz_questions(week_number,question,options_json,correct_index,explanation,is_active,created_at,updated_at) VALUES(11,'How should customer contact details be handled?','["Use only for authorized work and approved systems","Share in public groups","Save in personal social media"]',0,'Customer data must be handled responsibly.',1,'2026-11-05T13:30:00.000Z','2026-11-05T13:30:00.000Z');
INSERT OR IGNORE INTO quiz_questions(week_number,question,options_json,correct_index,explanation,is_active,created_at,updated_at) VALUES(11,'What should an agent do before discussing an account-specific matter?','["Follow the approved identity verification process","Share details with anyone who asks","Skip verification when busy"]',0,'Verification helps protect customer information.',1,'2026-11-05T13:30:00.000Z','2026-11-05T13:30:00.000Z');
INSERT OR IGNORE INTO quiz_questions(week_number,question,options_json,correct_index,explanation,is_active,created_at,updated_at) VALUES(11,'A customer''s password or OTP should be:','["Never requested or shared by the agent","Written in CRM notes","Sent to a colleague"]',0,'Passwords and OTPs are confidential security credentials.',1,'2026-11-05T13:30:00.000Z','2026-11-05T13:30:00.000Z');
INSERT OR IGNORE INTO quiz_questions(week_number,question,options_json,correct_index,explanation,is_active,created_at,updated_at) VALUES(12,'A strong next step at the end of a sales call is:','["A clear agreed action with an owner and timeframe","A vague ''we will see''","No summary"]',0,'Clear next steps keep the opportunity moving.',1,'2026-11-05T13:30:00.000Z','2026-11-05T13:30:00.000Z');
INSERT OR IGNORE INTO quiz_questions(week_number,question,options_json,correct_index,explanation,is_active,created_at,updated_at) VALUES(12,'When should a lead be marked as won?','["Only after the required confirmation and process are complete","As soon as the customer asks a question","Whenever the target is low"]',0,'Pipeline status must match verified outcomes.',1,'2026-11-05T13:30:00.000Z','2026-11-05T13:30:00.000Z');
INSERT OR IGNORE INTO quiz_questions(week_number,question,options_json,correct_index,explanation,is_active,created_at,updated_at) VALUES(12,'How should an agent prioritize follow-ups?','["Use agreed timelines, customer urgency and approved team priorities","Call only easy leads","Ignore older commitments"]',0,'Consistent prioritization protects customer commitments.',1,'2026-11-05T13:30:00.000Z','2026-11-05T13:30:00.000Z');
INSERT OR IGNORE INTO quiz_questions(week_number,question,options_json,correct_index,explanation,is_active,created_at,updated_at) VALUES(13,'A customer asks for a price but has not shared the required details. What should you do?','["Ask focused questions, capture requirements and explain the next step","Invent a price","Refuse to help"]',0,'Gather enough information before quoting.',1,'2026-11-05T13:30:00.000Z','2026-11-05T13:30:00.000Z');
INSERT OR IGNORE INTO quiz_questions(week_number,question,options_json,correct_index,explanation,is_active,created_at,updated_at) VALUES(13,'You notice a mismatch between the customer''s notes and the CRM record. What next?','["Verify the correct information and update through the approved process","Ignore the mismatch","Delete the record"]',0,'Verified corrections protect the customer journey.',1,'2026-11-05T13:30:00.000Z','2026-11-05T13:30:00.000Z');
INSERT OR IGNORE INTO quiz_questions(week_number,question,options_json,correct_index,explanation,is_active,created_at,updated_at) VALUES(13,'A customer requests an update you cannot confirm yet. What is best?','["Explain that you will verify it and give a realistic response time","Give a made-up update","Avoid responding"]',0,'Honest updates build trust.',1,'2026-11-05T13:30:00.000Z','2026-11-05T13:30:00.000Z');
